package org.example;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class AppTest {
    @Test void appHasAGreeting() {
        App classUnderTest = new App();
        assertNotNull(classUnderTest.getGreeting(), "app should have a greeting");
    }

    @Test void appGreetsByName() {
        App classUnderTest = new App();
        assertEquals("Hello, Ada!", classUnderTest.getGreeting("Ada"));
        assertEquals("Hello World!", classUnderTest.getGreeting(null));
        assertEquals("Hello World!", classUnderTest.getGreeting(""));
    }

    @Test void appDelegatesAddition() {
        App classUnderTest = new App();
        assertEquals(5, classUnderTest.add(2, 3));
    }
}
